# name: universal_word_singleton_rating
# description: Mean Likert rating of a probed visual singleton when the heard word is true of all objects in the scene and distractors are duplicated; tests under-prediction from M-implicature penalty.
_CACHE = {}

def test_statistic(df):
    if "idx" not in _CACHE:
        unique = df[["objects", "heard", "probe"]].drop_duplicates()
        matching = set()
        for _, r in unique.iterrows():
            if pd.notna(r["heard"]):
                objs = json.loads(r["objects"])
                h = int(r["heard"])
                p = int(r["probe"])
                if all(o[h] == 1 for o in objs):
                    if sum(1 for o in objs if o == objs[p]) == 1:
                        distractors = [o for i, o in enumerate(objs) if i != p]
                        if len(set(tuple(o) for o in distractors)) == 1:
                            if sum(objs[p]) <= sum(distractors[0]):
                                matching.add((r["objects"], h, p))
        keys = [(o, -1 if pd.isna(h) else int(h), p) for o, h, p in zip(df["objects"], df["heard"], df["probe"])]
        _CACHE["idx"] = np.where([k in matching for k in keys])[0]
    return float(df["rating"].iloc[_CACHE["idx"]].mean())

# name: asymmetric_5object_contrast_gap
# description: Difference in mean Likert rating between minimal target and duplicate competitor in 5-object asymmetric displays; tests under-production of pragmatic contrast in large scenes.
_CACHE = {}

def test_statistic(df):
    if "idx_min" not in _CACHE:
        unique = df[["objects", "heard", "probe"]].drop_duplicates()
        min_keys, comp_keys = set(), set()
        for _, r in unique.iterrows():
            objs = json.loads(r["objects"])
            if len(objs) == 5 and pd.notna(r["heard"]):
                h = int(r["heard"])
                if all(o[h] == 1 for o in objs):
                    p = int(r["probe"])
                    if sum(objs[p]) == 1:
                        min_keys.add((r["objects"], h, p))
                    elif sum(objs[p]) == 2:
                        comp_keys.add((r["objects"], h, p))
        keys = [(o, -1 if pd.isna(h) else int(h), p) for o, h, p in zip(df["objects"], df["heard"], df["probe"])]
        _CACHE["idx_min"] = np.where([k in min_keys for k in keys])[0]
        _CACHE["idx_comp"] = np.where([k in comp_keys for k in keys])[0]
    return float(df["rating"].iloc[_CACHE["idx_min"]].mean() - df["rating"].iloc[_CACHE["idx_comp"]].mean())

# name: scalar_competitor_unique_feature_rating
# description: Mean Likert rating of a probed scalar competitor possessing an unmentioned unique feature when distractors sharing the heard word are duplicated; tests spurious singleton prior preservation.
_CACHE = {}

def test_statistic(df):
    if "idx" not in _CACHE:
        unique = df[["objects", "heard", "probe"]].drop_duplicates()
        matching = set()
        for _, r in unique.iterrows():
            if pd.notna(r["heard"]):
                objs = json.loads(r["objects"])
                h = int(r["heard"])
                p = int(r["probe"])
                if objs[p][h] == 1 and sum(1 for o in objs if o == objs[p]) == 1:
                    comp_objs = [o for o in objs if o[h] == 1]
                    min_fc = min(sum(o) for o in comp_objs)
                    if sum(objs[p]) == min_fc + 1:
                        dup_min = any(comp_objs.count(o) > 1 for o in comp_objs if sum(o) == min_fc)
                        has_unique = any(objs[p][f] == 1 and sum(o[f] for o in objs) == 1 for f in range(len(objs[0])) if f != h)
                        if dup_min and has_unique:
                            matching.add((r["objects"], h, p))
        keys = [(o, -1 if pd.isna(h) else int(h), p) for o, h, p in zip(df["objects"], df["heard"], df["probe"])]
        _CACHE["idx"] = np.where([k in matching for k in keys])[0]
    return float(df["rating"].iloc[_CACHE["idx"]].mean())

